176→/**
177→ * Resolve a plugin by either database ID or plugin key.
178→ *
179→ * Lookup order:
180→ * - UUID-like IDs: getById first, then getByKey.
181→ * - Scoped package keys (e.g. "@scope/name"): getByKey only, never getById.
182→ * - Other non-UUID IDs: try getById first (test/memory registries may allow this),
183→ *   then fallback to getByKey. Any UUID parse error from getById is ignored.
184→ *
185→ * @param registry - The plugin registry service instance
186→ * @param pluginId - Either a database UUID or plugin key (manifest id)
187→ * @returns Plugin record or null if not found
188→ */
189→async function resolvePlugin(
190→  registry: ReturnType<typeof pluginRegistryService>,
191→  pluginId: string,
192→) {
193→  const isUuid = UUID_REGEX.test(pluginId);
194→  const isScopedPackageKey = pluginId.startsWith("@") || pluginId.includes("/");
195→
196→  // Scoped package IDs are valid plugin keys but invalid UUIDs.
197→  // Skip getById() entirely to avoid Postgres uuid parse errors.
198→  if (isScopedPackageKey && !isUuid) {
199→    return registry.getByKey(pluginId);
200→  }
201→
202→  try {
203→    const byId = await registry.getById(pluginId);
204→    if (byId) return byId;
205→  } catch (error) {
206→    const maybeCode =
207→      typeof error === "object" && error !== null && "code" in error
208→        ? (error as { code?: unknown }).code
209→        : undefined;
210→    // Ignore invalid UUID cast errors and continue with key lookup.
211→    if (maybeCode !== "22P02") {
212→      throw error;
213→    }
214→  }
215→
216→  return registry.getByKey(pluginId);
217→}
