 33→function firstNonEmptyLine(value: string | null | undefined): string | null {
 34→  if (!value) return null;
 35→  const line = value
 36→    .split(/\r?\n/)
 37→    .map((entry) => entry.trim())
 38→    .find(Boolean);
 39→  return line ?? null;
 40→}
 41→
 42→function getPluginErrorSummary(plugin: PluginRecord): string {
 43→  return firstNonEmptyLine(plugin.lastError) ?? "Plugin entered an error state without a stored error message.";
 44→}
