 46→/**
 47→ * PluginManager page component.
 48→ *
 49→ * Provides a management UI for the Paperclip plugin system:
 50→ * - Lists all installed plugins with their status, version, and category badges.
 51→ * - Allows installing new plugins by npm package name.
 52→ * - Provides per-plugin actions: enable, disable, navigate to settings.
 53→ * - Uninstall with a two-step confirmation dialog to prevent accidental removal.
 54→ *
 55→ * Data flow:
 56→ * - Reads from `GET /api/plugins` via `pluginsApi.list()`.
 57→ * - Mutations (install / uninstall / enable / disable) invalidate
 58→ *   `queryKeys.plugins.all` so the list refreshes automatically.
 59→ *
 60→ * @see PluginSettings — linked from the Settings icon on each plugin row.
 61→ * @see doc/plugins/PLUGIN_SPEC.md §3 — Plugin Lifecycle for status semantics.
 62→ */
 63→export function PluginManager() {
 64→  const { selectedCompany } = useCompany();
 65→  const { setBreadcrumbs } = useBreadcrumbs();
 66→  const queryClient = useQueryClient();
 67→  const { pushToast } = useToast();
 68→
 69→  const [installPackage, setInstallPackage] = useState("");
 70→  const [installDialogOpen, setInstallDialogOpen] = useState(false);
 71→  const [uninstallPluginId, setUninstallPluginId] = useState<string | null>(null);
 72→  const [uninstallPluginName, setUninstallPluginName] = useState<string>("");
 73→  const [errorDetailsPlugin, setErrorDetailsPlugin] = useState<PluginRecord | null>(null);
 74→
 75→  useEffect(() => {
 76→    setBreadcrumbs([
 77→      { label: selectedCompany?.name ?? "Company", href: "/dashboard" },
 78→      { label: "Settings", href: "/instance/settings/heartbeats" },
 79→      { label: "Plugins" },
 80→    ]);
 81→  }, [selectedCompany?.name, setBreadcrumbs]);
 82→
 83→  const { data: plugins, isLoading, error } = useQuery({
 84→    queryKey: queryKeys.plugins.all,
 85→    queryFn: () => pluginsApi.list(),
 86→  });
 87→
 88→  const examplesQuery = useQuery({
 89→    queryKey: queryKeys.plugins.examples,
 90→    queryFn: () => pluginsApi.listExamples(),
 91→  });
 92→
 93→  const invalidatePluginQueries = () => {
 94→    queryClient.invalidateQueries({ queryKey: queryKeys.plugins.all });
 95→    queryClient.invalidateQueries({ queryKey: queryKeys.plugins.examples });
 96→    queryClient.invalidateQueries({ queryKey: queryKeys.plugins.uiContributions });
 97→  };
 98→
 99→  const installMutation = useMutation({
100→    mutationFn: (params: { packageName: string; version?: string; isLocalPath?: boolean }) =>
101→      pluginsApi.install(params),
102→    onSuccess: () => {
103→      invalidatePluginQueries();
104→      setInstallDialogOpen(false);
105→      setInstallPackage("");
106→      pushToast({ title: "Plugin installed successfully", tone: "success" });
107→    },
108→    onError: (err: Error) => {
109→      pushToast({ title: "Failed to install plugin", body: err.message, tone: "error" });
110→    },
111→  });
112→
113→  const uninstallMutation = useMutation({
114→    mutationFn: (pluginId: string) => pluginsApi.uninstall(pluginId),
115→    onSuccess: () => {
116→      invalidatePluginQueries();
117→      pushToast({ title: "Plugin uninstalled successfully", tone: "success" });
118→    },
119→    onError: (err: Error) => {
120→      pushToast({ title: "Failed to uninstall plugin", body: err.message, tone: "error" });
121→    },
122→  });
123→
124→  const enableMutation = useMutation({
125→    mutationFn: (pluginId: string) => pluginsApi.enable(pluginId),
126→    onSuccess: () => {
127→      invalidatePluginQueries();
128→      pushToast({ title: "Plugin enabled", tone: "success" });
129→    },
130→    onError: (err: Error) => {
131→      pushToast({ title: "Failed to enable plugin", body: err.message, tone: "error" });
132→    },
133→  });
134→
135→  const disableMutation = useMutation({
136→    mutationFn: (pluginId: string) => pluginsApi.disable(pluginId),
137→    onSuccess: () => {
138→      invalidatePluginQueries();
139→      pushToast({ title: "Plugin disabled", tone: "info" });
140→    },
141→    onError: (err: Error) => {
142→      pushToast({ title: "Failed to disable plugin", body: err.message, tone: "error" });
143→    },
144→  });
145→
146→  const installedPlugins = plugins ?? [];
147→  const examples = examplesQuery.data ?? [];
148→  const installedByPackageName = new Map(installedPlugins.map((plugin) => [plugin.packageName, plugin]));
149→  const examplePackageNames = new Set(examples.map((example) => example.packageName));
150→  const errorSummaryByPluginId = useMemo(
151→    () =>
152→      new Map(
153→        installedPlugins.map((plugin) => [plugin.id, getPluginErrorSummary(plugin)])
154→      ),
155→    [installedPlugins]
156→  );
157→
158→  if (isLoading) return <div className="p-4 text-sm text-muted-foreground">Loading plugins...</div>;
159→  if (error) return <div className="p-4 text-sm text-destructive">Failed to load plugins.</div>;
160→
161→  return (
162→    <div className="space-y-6 max-w-5xl">
163→      <div className="flex items-center justify-between">
164→        <div className="flex items-center gap-2">
165→          <Puzzle className="h-6 w-6 text-muted-foreground" />
166→          <h1 className="text-xl font-semibold">Plugin Manager</h1>
167→        </div>
168→        
169→        <Dialog open={installDialogOpen} onOpenChange={setInstallDialogOpen}>
170→          <DialogTrigger asChild>
171→            <Button size="sm" className="gap-2">
172→              <Plus className="h-4 w-4" />
173→              Install Plugin
174→            </Button>
175→          </DialogTrigger>
176→          <DialogContent>
177→            <DialogHeader>
178→              <DialogTitle>Install Plugin</DialogTitle>
179→              <DialogDescription>
180→                Enter the npm package name of the plugin you wish to install.
181→              </DialogDescription>
182→            </DialogHeader>
183→            <div className="grid gap-4 py-4">
184→              <div className="grid gap-2">
185→                <Label htmlFor="packageName">npm Package Name</Label>
186→                <Input
187→                  id="packageName"
188→                  placeholder="@paperclipai/plugin-example"
189→                  value={installPackage}
190→                  onChange={(e) => setInstallPackage(e.target.value)}
191→                />
192→              </div>
193→            </div>
194→            <DialogFooter>
195→              <Button variant="outline" onClick={() => setInstallDialogOpen(false)}>Cancel</Button>
196→              <Button
197→                onClick={() => installMutation.mutate({ packageName: installPackage })}
198→                disabled={!installPackage || installMutation.isPending}
199→              >
200→                {installMutation.isPending ? "Installing..." : "Install"}
201→              </Button>
202→            </DialogFooter>
203→          </DialogContent>
204→        </Dialog>
205→      </div>
206→
207→      <div className="rounded-lg border border-amber-500/30 bg-amber-500/5 px-4 py-3">
208→        <div className="flex items-start gap-3">
209→          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-700" />
210→          <div className="space-y-1 text-sm">
211→            <p className="font-medium text-foreground">Plugins are alpha.</p>
212→            <p className="text-muted-foreground">
213→              The plugin runtime and API surface are still changing. Expect breaking changes while this feature settles.
214→            </p>
215→          </div>
216→        </div>
217→      </div>
218→
219→      <section className="space-y-3">
220→        <div className="flex items-center gap-2">
221→          <FlaskConical className="h-5 w-5 text-muted-foreground" />
222→          <h2 className="text-base font-semibold">Available Plugins</h2>
223→          <Badge variant="outline">Examples</Badge>
224→        </div>
225→
226→        {examplesQuery.isLoading ? (
227→          <div className="text-sm text-muted-foreground">Loading bundled examples...</div>
228→        ) : examplesQuery.error ? (
229→          <div className="text-sm text-destructive">Failed to load bundled examples.</div>
230→        ) : examples.length === 0 ? (
231→          <div className="rounded-md border border-dashed px-4 py-3 text-sm text-muted-foreground">
232→            No bundled example plugins were found in this checkout.
233→          </div>
234→        ) : (
235→          <ul className="divide-y rounded-md border bg-card">
236→            {examples.map((example) => {
237→              const installedPlugin = installedByPackageName.get(example.packageName);
238→              const installPending =
239→                installMutation.isPending &&
240→                installMutation.variables?.isLocalPath &&
241→                installMutation.variables.packageName === example.localPath;
242→
243→              return (
244→                <li key={example.packageName}>
245→                  <div className="flex items-center gap-4 px-4 py-3">
246→                    <div className="min-w-0 flex-1">
247→                      <div className="flex flex-wrap items-center gap-2">
248→                        <span className="font-medium">{example.displayName}</span>
249→                        <Badge variant="outline">Example</Badge>
250→                        {installedPlugin ? (
251→                          <Badge
252→                            variant={installedPlugin.status === "ready" ? "default" : "secondary"}
253→                            className={installedPlugin.status === "ready" ? "bg-green-600 hover:bg-green-700" : ""}
254→                          >
255→                            {installedPlugin.status}
256→                          </Badge>
257→                        ) : (
258→                          <Badge variant="secondary">Not installed</Badge>
259→                        )}
260→                      </div>
261→                      <p className="mt-1 text-sm text-muted-foreground">{example.description}</p>
262→                      <p className="mt-1 text-xs text-muted-foreground">{example.packageName}</p>
263→                    </div>
264→                    <div className="flex items-center gap-2 shrink-0">
265→                      {installedPlugin ? (
266→                        <>
267→                          {installedPlugin.status !== "ready" && (
268→                            <Button
269→                              variant="outline"
270→                              size="sm"
271→                              disabled={enableMutation.isPending}
272→                              onClick={() => enableMutation.mutate(installedPlugin.id)}
273→                            >
274→                              Enable
275→                            </Button>
276→                          )}
277→                          <Button variant="outline" size="sm" asChild>
278→                            <Link to={`/instance/settings/plugins/${installedPlugin.id}`}>
279→                              {installedPlugin.status === "ready" ? "Open Settings" : "Review"}
280→                            </Link>
281→                          </Button>
282→                        </>
283→                      ) : (
284→                        <Button
285→                          size="sm"
286→                          disabled={installPending || installMutation.isPending}
287→                          onClick={() =>
288→                            installMutation.mutate({
289→                              packageName: example.localPath,
290→                              isLocalPath: true,
291→                            })
292→                          }
293→                        >
294→                          {installPending ? "Installing..." : "Install Example"}
295→                        </Button>
296→                      )}
297→                    </div>
298→                  </div>
299→                </li>
300→              );
301→            })}
302→          </ul>
303→        )}
304→      </section>
305→
306→      <section className="space-y-3">
307→        <div className="flex items-center gap-2">
308→          <Puzzle className="h-5 w-5 text-muted-foreground" />
309→          <h2 className="text-base font-semibold">Installed Plugins</h2>
310→        </div>
311→
312→        {!installedPlugins.length ? (
313→          <Card className="bg-muted/30">
314→            <CardContent className="flex flex-col items-center justify-center py-10">
315→              <Puzzle className="h-10 w-10 text-muted-foreground mb-4" />
