525→   *
526→   * Execute a plugin-contributed tool by its namespaced name.
527→   *
528→   * This is the primary endpoint used by the agent service to invoke
529→   * plugin tools during an agent run.
530→   *
531→   * Request body:
532→   * - `tool`: Fully namespaced tool name (e.g., "acme.linear:search-issues")
533→   * - `parameters`: Parameters matching the tool's declared JSON Schema
534→   * - `runContext`: Agent run context with agentId, runId, companyId, projectId
535→   *
536→   * Response: `ToolExecutionResult`
537→   * Errors:
538→   * - 400 if request validation fails
539→   * - 404 if tool is not found
540→   * - 501 if tool dispatcher is not configured
541→   * - 502 if the plugin worker is unavailable or the RPC call fails
542→   */
543→  router.post("/plugins/tools/execute", async (req, res) => {
544→    assertBoard(req);
545→
546→    if (!toolDeps) {
547→      res.status(501).json({ error: "Plugin tool dispatch is not enabled" });
548→      return;
549→    }
550→
551→    const body = (req.body as PluginToolExecuteRequest | undefined);
552→    if (!body) {
553→      res.status(400).json({ error: "Request body is required" });
554→      return;
555→    }
556→
557→    const { tool, parameters, runContext } = body;
558→
559→    // Validate required fields
560→    if (!tool || typeof tool !== "string") {
561→      res.status(400).json({ error: '"tool" is required and must be a string' });
562→      return;
563→    }
564→
565→    if (!runContext || typeof runContext !== "object") {
566→      res.status(400).json({ error: '"runContext" is required and must be an object' });
567→      return;
568→    }
569→
570→    if (!runContext.agentId || !runContext.runId || !runContext.companyId || !runContext.projectId) {
571→      res.status(400).json({
572→        error: '"runContext" must include agentId, runId, companyId, and projectId',
573→      });
574→      return;
575→    }
576→
577→    assertCompanyAccess(req, runContext.companyId);
578→
579→    // Verify the tool exists
580→    const registeredTool = toolDeps.toolDispatcher.getTool(tool);
581→    if (!registeredTool) {
582→      res.status(404).json({ error: `Tool "${tool}" not found` });
583→      return;
584→    }
585→
586→    try {
587→      const result = await toolDeps.toolDispatcher.executeTool(
588→        tool,
589→        parameters ?? {},
590→        runContext,
591→      );
592→      res.json(result);
593→    } catch (err) {
594→      const message = err instanceof Error ? err.message : String(err);
595→
596→      // Distinguish between "worker not running" (502) and other errors (500)
597→      if (message.includes("not running") || message.includes("worker")) {
598→        res.status(502).json({ error: message });
599→      } else {
600→        res.status(500).json({ error: message });
601→      }
602→    }
603→  });
