154→export function hasAgentShortnameCollision(
155→  candidateName: string,
156→  existingAgents: AgentShortnameRow[],
157→  options?: AgentShortnameCollisionOptions,
158→): boolean {
159→  const candidateShortname = normalizeAgentUrlKey(candidateName);
160→  if (!candidateShortname) return false;
161→
162→  return existingAgents.some((agent) => {
163→    if (agent.status === "terminated") return false;
164→    if (options?.excludeAgentId && agent.id === options.excludeAgentId) return false;
165→    return normalizeAgentUrlKey(agent.name) === candidateShortname;
166→  });
167→}
