169→export function deduplicateAgentName(
170→  candidateName: string,
171→  existingAgents: AgentShortnameRow[],
172→): string {
173→  if (!hasAgentShortnameCollision(candidateName, existingAgents)) {
174→    return candidateName;
175→  }
176→  for (let i = 2; i <= 100; i++) {
177→    const suffixed = `${candidateName} ${i}`;
178→    if (!hasAgentShortnameCollision(suffixed, existingAgents)) {
179→      return suffixed;
180→    }
181→  }
182→  return `${candidateName} ${Date.now()}`;
183→}
