215→        spentMonthlyCents: sql<number>`coalesce(sum(${costEvents.costCents}), 0)::int`,
216→      })
217→      .from(costEvents)
218→      .where(
219→        and(
220→          eq(costEvents.companyId, companyId),
221→          inArray(costEvents.agentId, agentIds),
222→          gte(costEvents.occurredAt, start),
223→          lt(costEvents.occurredAt, end),
224→        ),
225→      )
226→      .groupBy(costEvents.agentId);
227→    return new Map(rows.map((row) => [row.agentId, Number(row.spentMonthlyCents ?? 0)]));
228→  }
