322→      await assertNoCycle(id, data.reportsTo);
323→    }
324→
325→    if (data.name !== undefined) {
326→      const previousShortname = normalizeAgentUrlKey(existing.name);
327→      const nextShortname = normalizeAgentUrlKey(data.name);
328→      if (previousShortname !== nextShortname) {
