330→      }
331→    }
332→
333→    const normalizedPatch = { ...data } as Partial<typeof agents.$inferInsert>;
334→    if (data.permissions !== undefined) {
335→      const role = (data.role ?? existing.role) as string;
336→      normalizedPatch.permissions = normalizeAgentPermissions(data.permissions, role);
337→    }
338→
339→    const shouldRecordRevision = Boolean(options?.recordRevision) && hasConfigPatchFields(normalizedPatch);
340→    const beforeConfig = shouldRecordRevision ? buildConfigSnapshot(existing) : null;
341→
342→    const updated = await db
343→      .update(agents)
344→      .set({ ...normalizedPatch, updatedAt: new Date() })
345→      .where(eq(agents.id, id))
346→      .returning()
347→      .then((rows) => rows[0] ?? null);
348→    const normalizedUpdated = updated ? normalizeAgentRow(updated) : null;
349→
350→    if (normalizedUpdated && shouldRecordRevision && beforeConfig) {
351→      const afterConfig = buildConfigSnapshot(normalizedUpdated);
352→      const changedKeys = diffConfigSnapshot(beforeConfig, afterConfig);
353→      if (changedKeys.length > 0) {
