359→          source: options?.recordRevision?.source ?? "patch",
360→          rolledBackFromRevisionId: options?.recordRevision?.rolledBackFromRevisionId ?? null,
361→          changedKeys,
362→          beforeConfig: beforeConfig as unknown as Record<string, unknown>,
363→          afterConfig: afterConfig as unknown as Record<string, unknown>,
364→        });
365→      }
366→    }
367→
368→    return normalizedUpdated;
369→  }
