619→        .where(and(eq(agents.companyId, companyId), ne(agents.status, "terminated")));
620→      const normalizedRows = rows.map(normalizeAgentRow);
621→      const byManager = new Map<string | null, typeof normalizedRows>();
622→      for (const row of normalizedRows) {
623→        const key = row.reportsTo ?? null;
624→        const group = byManager.get(key) ?? [];
625→        group.push(row);
626→        byManager.set(key, group);
627→      }
628→
629→      const build = (managerId: string | null): Array<Record<string, unknown>> => {
630→        const members = byManager.get(managerId) ?? [];
631→        return members.map((member) => ({
632→          ...member,
633→          reports: build(member.id),
634→        }));
635→      };
636→
637→      return build(null);
638→    },
