640→    getChainOfCommand: async (agentId: string) => {
641→      const chain: { id: string; name: string; role: string; title: string | null }[] = [];
642→      const visited = new Set<string>([agentId]);
643→      const start = await getById(agentId);
644→      let currentId = start?.reportsTo ?? null;
645→      while (currentId && !visited.has(currentId) && chain.length < 50) {
646→        visited.add(currentId);
647→        const mgr = await getById(currentId);
648→        if (!mgr) break;
649→        chain.push({ id: mgr.id, name: mgr.name, role: mgr.role, title: mgr.title ?? null });
650→        currentId = mgr.reportsTo ?? null;
651→      }
652→      return chain;
653→    },
