661→    resolveByReference: async (companyId: string, reference: string) => {
662→      const raw = reference.trim();
663→      if (raw.length === 0) {
664→        return { agent: null, ambiguous: false } as const;
665→      }
666→
667→      if (isUuidLike(raw)) {
668→        const byId = await getById(raw);
669→        if (!byId || byId.companyId !== companyId) {
670→          return { agent: null, ambiguous: false } as const;
671→        }
672→        return { agent: byId, ambiguous: false } as const;
673→      }
674→
675→      const urlKey = normalizeAgentUrlKey(raw);
676→      if (!urlKey) {
677→        return { agent: null, ambiguous: false } as const;
678→      }
679→
680→      const rows = await db.select().from(agents).where(eq(agents.companyId, companyId));
681→      const matches = rows
682→        .map(normalizeAgentRow)
683→        .filter((agent) => agent.urlKey === urlKey && agent.status !== "terminated");
684→      if (matches.length === 1) {
685→        return { agent: matches[0] ?? null, ambiguous: false } as const;
686→      }
687→      if (matches.length > 1) {
688→        return { agent: null, ambiguous: true } as const;
689→      }
690→      return { agent: null, ambiguous: false } as const;
691→    },
692→  };
693→}
