109→  async function buildAgentAccessState(agent: NonNullable<Awaited<ReturnType<typeof svc.getById>>>) {
110→    const membership = await access.getMembership(agent.companyId, "agent", agent.id);
111→    const grants = membership
112→      ? await access.listPrincipalGrants(agent.companyId, "agent", agent.id)
113→      : [];
114→    const hasExplicitTaskAssignGrant = grants.some((grant) => grant.permissionKey === "tasks:assign");
115→
116→    if (agent.role === "ceo") {
117→      return {
118→        canAssignTasks: true,
119→        taskAssignSource: "ceo_role" as const,
120→        membership,
121→        grants,
122→      };
123→    }
124→
125→    if (canCreateAgents(agent)) {
126→      return {
127→        canAssignTasks: true,
128→        taskAssignSource: "agent_creator" as const,
129→        membership,
130→        grants,
131→      };
132→    }
133→
134→    if (hasExplicitTaskAssignGrant) {
135→      return {
136→        canAssignTasks: true,
137→        taskAssignSource: "explicit_grant" as const,
138→        membership,
139→        grants,
140→      };
141→    }
142→
143→    return {
144→      canAssignTasks: false,
145→      taskAssignSource: "none" as const,
146→      membership,
147→      grants,
