183→  async function assertCanCreateAgentsForCompany(req: Request, companyId: string) {
184→    assertCompanyAccess(req, companyId);
185→    if (req.actor.type === "board") {
186→      if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return null;
187→      const allowed = await access.canUser(companyId, req.actor.userId, "agents:create");
188→      if (!allowed) {
189→        throw forbidden("Missing permission: agents:create");
190→      }
191→      return null;
192→    }
193→    if (!req.actor.agentId) throw forbidden("Agent authentication required");
194→    const actorAgent = await svc.getById(req.actor.agentId);
195→    if (!actorAgent || actorAgent.companyId !== companyId) {
196→      throw forbidden("Agent key cannot access another company");
197→    }
198→    const allowedByGrant = await access.hasPermission(companyId, "agent", actorAgent.id, "agents:create");
199→    if (!allowedByGrant && !canCreateAgents(actorAgent)) {
200→      throw forbidden("Missing permission: can create agents");
201→    }
202→    return actorAgent;
203→  }
