209→  async function actorCanReadConfigurationsForCompany(req: Request, companyId: string) {
210→    assertCompanyAccess(req, companyId);
211→    if (req.actor.type === "board") {
212→      if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return true;
213→      return access.canUser(companyId, req.actor.userId, "agents:create");
