222→  async function assertCanUpdateAgent(req: Request, targetAgent: { id: string; companyId: string }) {
223→    assertCompanyAccess(req, targetAgent.companyId);
224→    if (req.actor.type === "board") return;
225→    if (!req.actor.agentId) throw forbidden("Agent authentication required");
226→
227→    const actorAgent = await svc.getById(req.actor.agentId);
228→    if (!actorAgent || actorAgent.companyId !== targetAgent.companyId) {
229→      throw forbidden("Agent key cannot access another company");
230→    }
231→
232→    if (actorAgent.id === targetAgent.id) return;
233→    if (actorAgent.role === "ceo") return;
234→    const allowedByGrant = await access.hasPermission(
235→      targetAgent.companyId,
236→      "agent",
237→      actorAgent.id,
238→      "agents:create",
239→    );
240→    if (allowedByGrant || canCreateAgents(actorAgent)) return;
241→    throw forbidden("Only CEO or agent creators can modify other agents");
