244→  async function assertCanReadAgent(req: Request, targetAgent: { companyId: string }) {
245→    assertCompanyAccess(req, targetAgent.companyId);
246→    if (req.actor.type === "board") return;
247→    if (!req.actor.agentId) throw forbidden("Agent authentication required");
248→
249→    const actorAgent = await svc.getById(req.actor.agentId);
250→    if (!actorAgent || actorAgent.companyId !== targetAgent.companyId) {
251→      throw forbidden("Agent key cannot access another company");
252→    }
253→  }
