255→  async function resolveCompanyIdForAgentReference(req: Request): Promise<string | null> {
256→    const companyIdQuery = req.query.companyId;
257→    const requestedCompanyId =
258→      typeof companyIdQuery === "string" && companyIdQuery.trim().length > 0
259→        ? companyIdQuery.trim()
260→        : null;
261→    if (requestedCompanyId) {
262→      assertCompanyAccess(req, requestedCompanyId);
263→      return requestedCompanyId;
264→    }
265→    if (req.actor.type === "agent" && req.actor.companyId) {
266→      return req.actor.companyId;
267→    }
268→    return null;
269→  }
270→
271→  async function normalizeAgentReference(req: Request, rawId: string): Promise<string> {
272→    const raw = rawId.trim();
273→    if (isUuidLike(raw)) return raw;
274→
275→    const companyId = await resolveCompanyIdForAgentReference(req);
276→    if (!companyId) {
277→      throw unprocessable("Agent shortname lookup requires companyId query parameter");
278→    }
279→
280→    const resolved = await svc.resolveByReference(companyId, raw);
281→    if (resolved.ambiguous) {
282→      throw conflict("Agent shortname is ambiguous in this company. Use the agent ID.");
283→    }
284→    if (!resolved.agent) {
285→      throw notFound("Agent not found");
286→    }
287→    return resolved.agent.id;
288→  }
