290→  function parseSourceIssueIds(input: {
291→    sourceIssueId?: string | null;
292→    sourceIssueIds?: string[];
293→  }): string[] {
294→    const values: string[] = [];
295→    if (Array.isArray(input.sourceIssueIds)) values.push(...input.sourceIssueIds);
296→    if (typeof input.sourceIssueId === "string" && input.sourceIssueId.length > 0) {
297→      values.push(input.sourceIssueId);
298→    }
299→    return Array.from(new Set(values));
300→  }

