331→  function parseBooleanLike(value: unknown): boolean | null {
332→    if (typeof value === "boolean") return value;
333→    if (typeof value === "number") {
334→      if (value === 1) return true;
335→      if (value === 0) return false;
336→      return null;
337→    }
338→    if (typeof value !== "string") return null;
339→    const normalized = value.trim().toLowerCase();
340→    if (normalized === "true" || normalized === "1" || normalized === "yes" || normalized === "on") {
341→      return true;
342→    }
343→    if (normalized === "false" || normalized === "0" || normalized === "no" || normalized === "off") {
344→      return false;
345→    }
346→    return null;
347→  }
348→
349→  function parseNumberLike(value: unknown): number | null {
350→    if (typeof value === "number" && Number.isFinite(value)) return value;
351→    if (typeof value !== "string") return null;
352→    const parsed = Number(value.trim());
353→    return Number.isFinite(parsed) ? parsed : null;
354→  }
