369→  function ensureGatewayDeviceKey(
370→    adapterType: string | null | undefined,
371→    adapterConfig: Record<string, unknown>,
372→  ): Record<string, unknown> {
373→    if (adapterType !== "openclaw_gateway") return adapterConfig;
374→    const disableDeviceAuth = parseBooleanLike(adapterConfig.disableDeviceAuth) === true;
375→    if (disableDeviceAuth) return adapterConfig;
376→    if (asNonEmptyString(adapterConfig.devicePrivateKeyPem)) return adapterConfig;
377→    return { ...adapterConfig, devicePrivateKeyPem: generateEd25519PrivateKeyPem() };
378→  }
