380→  function applyCreateDefaultsByAdapterType(
381→    adapterType: string | null | undefined,
382→    adapterConfig: Record<string, unknown>,
383→  ): Record<string, unknown> {
384→    const next = { ...adapterConfig };
385→    if (adapterType === "codex_local") {
386→      if (!asNonEmptyString(next.model)) {
387→        next.model = DEFAULT_CODEX_LOCAL_MODEL;
388→      }
389→      const hasBypassFlag =
390→        typeof next.dangerouslyBypassApprovalsAndSandbox === "boolean" ||
391→        typeof next.dangerouslyBypassSandbox === "boolean";
392→      if (!hasBypassFlag) {
393→        next.dangerouslyBypassApprovalsAndSandbox = DEFAULT_CODEX_LOCAL_BYPASS_APPROVALS_AND_SANDBOX;
394→      }
395→      return ensureGatewayDeviceKey(adapterType, next);
396→    }
397→    if (adapterType === "gemini_local" && !asNonEmptyString(next.model)) {
398→      next.model = DEFAULT_GEMINI_LOCAL_MODEL;
399→      return ensureGatewayDeviceKey(adapterType, next);
400→    }
401→    // OpenCode requires explicit model selection — no default
402→    if (adapterType === "cursor" && !asNonEmptyString(next.model)) {
403→      next.model = DEFAULT_CURSOR_LOCAL_MODEL;
404→    }
405→    return ensureGatewayDeviceKey(adapterType, next);
406→  }
