429→  function resolveInstructionsFilePath(candidatePath: string, adapterConfig: Record<string, unknown>) {
430→    const trimmed = candidatePath.trim();
431→    if (path.isAbsolute(trimmed)) return trimmed;
432→
433→    const cwd = asNonEmptyString(adapterConfig.cwd);
434→    if (!cwd) {
435→      throw unprocessable(
